import {
  useCallback,
  useEffect,
  useMemo,
  useRef,
  useState,
  type CSSProperties,
  type PointerEvent as ReactPointerEvent,
} from "react";
import { IconArrowUpRight, IconBurst, IconPause, IconPlay } from "../components/Icons";
import { getSource, specimenById } from "../content";
import { navigateToStructure } from "../lib/navigation";
import { useSlidingPill } from "../lib/use-sliding-pill";
import {
  SIM_HEIGHT,
  SIM_WIDTH,
  createBilayerSimulation,
  disruptBilayer,
  getBilayerTelemetry,
  resetBilayerSimulation,
  sameBilayerTelemetry,
  stepBilayerSimulation,
  type BilayerPreset,
  type BilayerSimulation,
  type BilayerStatus,
  type BilayerTelemetry,
  type SimulationSpeed,
} from "../sim/bilayer-engine";
import { renderBilayerFrame } from "../sim/bilayer-renderer";

const STATUS_LABELS: Record<BilayerStatus, string> = {
  disrupted: "disrupted",
  forming: "forming",
  formed: "formed",
};

const EXPLANATIONS: Record<BilayerStatus, { badge: string; heading: string; body: string }> = {
  disrupted: {
    badge: "Disrupted",
    heading: "Membrane dispersed into water",
    body: "The impact scattered both phospholipids and water molecules across the chamber, exposing hydrophobic tails to water. Random thermal collisions immediately start driving spontaneous re-assembly.",
  },
  forming: {
    badge: "Self-assembly",
    heading: "Tails hide from water, heads face water",
    body: "Molecules move in constant thermal motion, and every collision favors contacts where tails tuck beside other tails while hydrophilic heads face water. Notice the warm golden glow as tails shield one another—order emerges naturally from the hydrophobic effect without any central controller.",
  },
  formed: {
    badge: "Bilayer",
    heading: "A double layer has formed",
    body: "All hydrophobic tails are tucked inside a continuous golden core while hydrophilic heads face water on both sides. A single monolayer is unstable in water because one surface remains hydrophobic, so phospholipids form a bilayer. Tap or click anywhere on the membrane to disrupt it and watch it restore.",
  },
};

const MEMBRANE_SPECIMEN_IDS = [
  "animal-cell",
  "plant-cell",
  "bacteria",
  "red-blood-cell",
  "white-blood-cell",
  "yeast-cell",
] as const;

export function BilayerSimulator({
  reduceMotion,
  resolvedTheme,
}: {
  reduceMotion: boolean;
  resolvedTheme: "light" | "dark";
}) {
  const initialPreset: BilayerPreset = reduceMotion ? "formed" : "random";
  const [preset, setPreset] = useState<BilayerPreset>(initialPreset);
  const [speed, setSpeed] = useState<SimulationSpeed>(1);
  const [running, setRunning] = useState<boolean>(() => !reduceMotion);
  const [showExplanations, setShowExplanations] = useState(true);

  const seedCounterRef = useRef(20261123);
  const simRef = useRef<BilayerSimulation | null>(null);
  if (!simRef.current) {
    simRef.current = createBilayerSimulation({
      preset: initialPreset,
      seed: seedCounterRef.current,
    });
  }

  const [telemetry, setTelemetry] = useState<BilayerTelemetry>(() =>
    getBilayerTelemetry(simRef.current!),
  );
  const syncTelemetry = useCallback((sim: BilayerSimulation) => {
    const next = getBilayerTelemetry(sim);
    setTelemetry((prev) => (sameBilayerTelemetry(prev, next) ? prev : next));
  }, []);

  const canvasRef = useRef<HTMLCanvasElement>(null);
  const stageRef = useRef<HTMLDivElement>(null);
  const sizeRef = useRef<{ width: number; height: number; dpr: number }>({
    width: SIM_WIDTH,
    height: SIM_HEIGHT,
    dpr: 1,
  });

  const speedRef = useRef<SimulationSpeed>(speed);
  speedRef.current = speed;
  const themeRef = useRef(resolvedTheme);
  themeRef.current = resolvedTheme;
  const runningRef = useRef(running);
  runningRef.current = running;

  const speedPill = useSlidingPill<HTMLButtonElement>(speed === 1 ? 0 : 1, reduceMotion);
  const presetPill = useSlidingPill<HTMLButtonElement>(preset === "random" ? 0 : 1, reduceMotion);

  const membraneSpecimens = useMemo(
    () =>
      MEMBRANE_SPECIMEN_IDS.flatMap((id) => {
        const specimen = specimenById(id);
        return specimen ? [specimen] : [];
      }),
    [],
  );

  const ncbiSource = getSource("ncbi-mboc");
  const openStaxSource = getSource("openstax-bio-4-3");

  const drawFrame = useCallback(() => {
    const canvas = canvasRef.current;
    const sim = simRef.current;
    if (!canvas || !sim) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    const { width, height, dpr } = sizeRef.current;
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    renderBilayerFrame(ctx, sim, width, height, themeRef.current);
  }, []);

  const syncCanvasDimensions = useCallback(() => {
    const canvas = canvasRef.current;
    const stage = stageRef.current;
    if (!canvas || !stage) return;

    const rect = stage.getBoundingClientRect();
    const width = Math.max(240, Math.round(rect.width));
    const height = Math.max(160, Math.round(rect.height));
    const dpr = Math.min(window.devicePixelRatio || 1, 2);

    sizeRef.current = { width, height, dpr };
    const targetW = Math.round(width * dpr);
    const targetH = Math.round(height * dpr);
    if (canvas.width !== targetW || canvas.height !== targetH) {
      canvas.width = targetW;
      canvas.height = targetH;
    }
    drawFrame();
  }, [drawFrame]);

  useEffect(() => {
    syncCanvasDimensions();
    const stage = stageRef.current;
    if (!stage || typeof ResizeObserver === "undefined") return;
    const observer = new ResizeObserver(() => syncCanvasDimensions());
    observer.observe(stage);
    return () => observer.disconnect();
  }, [syncCanvasDimensions]);

  useEffect(() => {
    drawFrame();
  }, [resolvedTheme, drawFrame]);

  useEffect(() => {
    if (reduceMotion) {
      setRunning(false);
    }
  }, [reduceMotion]);

  useEffect(() => {
    if (!running) {
      drawFrame();
      return;
    }

    let rafId = 0;
    let lastTime = performance.now();
    let lastTelemetryPush = lastTime;

    const schedule = () => {
      if (rafId !== 0 || document.hidden || !runningRef.current) return;
      lastTime = performance.now();
      rafId = requestAnimationFrame(tick);
    };

    const stop = () => {
      if (rafId !== 0) {
        cancelAnimationFrame(rafId);
        rafId = 0;
      }
    };

    const tick = (now: number) => {
      rafId = 0;
      if (!runningRef.current || document.hidden) return;
      const dt = Math.max(0, (now - lastTime) / 1000);
      lastTime = now;

      const sim = simRef.current;
      if (sim) {
        stepBilayerSimulation(sim, dt, speedRef.current);
        drawFrame();

        if (now - lastTelemetryPush >= 100) {
          lastTelemetryPush = now;
          syncTelemetry(sim);
        }
      }
      rafId = requestAnimationFrame(tick);
    };

    const handleVisibility = () => {
      if (document.hidden) {
        stop();
      } else {
        schedule();
      }
    };
    document.addEventListener("visibilitychange", handleVisibility);
    schedule();

    return () => {
      stop();
      document.removeEventListener("visibilitychange", handleVisibility);
    };
  }, [running, drawFrame, syncTelemetry]);

  const handleReset = (nextPreset: BilayerPreset) => {
    const sim = simRef.current;
    if (!sim) return;
    seedCounterRef.current += 1;
    resetBilayerSimulation(sim, nextPreset, seedCounterRef.current);
    setPreset(nextPreset);
    syncTelemetry(sim);
    drawFrame();
  };

  const handleDisruptAt = (nx: number, ny: number) => {
    const sim = simRef.current;
    if (!sim) return;
    disruptBilayer(sim, nx, ny);
    syncTelemetry(sim);
    if (!running && !reduceMotion) {
      setRunning(true);
    }
    drawFrame();
  };

  const handleStep = () => {
    const sim = simRef.current;
    if (!sim) return;
    stepBilayerSimulation(sim, 0.1, speed);
    syncTelemetry(sim);
    drawFrame();
  };

  const handleCanvasPointerDown = (event: ReactPointerEvent<HTMLCanvasElement>) => {
    if (event.button !== 0 && event.pointerType === "mouse") return;
    const canvas = canvasRef.current;
    if (!canvas) return;
    const rect = canvas.getBoundingClientRect();
    if (rect.width <= 0 || rect.height <= 0) return;
    const nx = (event.clientX - rect.left) / rect.width;
    const ny = (event.clientY - rect.top) / rect.height;
    handleDisruptAt(nx, ny);
  };

  const explanation = EXPLANATIONS[telemetry.status];

  return (
    <>
      <section className="lab-card" aria-label="Phospholipid bilayer simulator">
        <div className="lab-toolbar">
          <div
            className="segmented"
            role="group"
            aria-label="Simulation speed"
            ref={speedPill.containerRef}
          >
            <span className="spring-pill" aria-hidden="true" ref={speedPill.pillRef} />
            <button
              ref={speedPill.registerItem(0)}
              type="button"
              aria-pressed={speed === 1}
              onClick={() => setSpeed(1)}
            >
              1×
            </button>
            <button
              ref={speedPill.registerItem(1)}
              type="button"
              aria-pressed={speed === 2}
              onClick={() => setSpeed(2)}
            >
              2×
            </button>
          </div>

          <button
            type="button"
            className="button button--ghost"
            aria-pressed={running}
            onClick={() => setRunning((prev) => !prev)}
          >
            {running ? <IconPause /> : <IconPlay />}
            <span>{running ? "Pause" : "Play"}</span>
          </button>

          {!running && (
            <button type="button" className="button button--ghost" onClick={handleStep}>
              Step
            </button>
          )}

          <button
            type="button"
            className="button button--ghost"
            onClick={() => handleDisruptAt(0.5, 0.5)}
          >
            <IconBurst />
            <span>Disrupt membrane</span>
          </button>

          <button
            type="button"
            role="switch"
            aria-checked={showExplanations}
            className="lab-switch"
            onClick={() => setShowExplanations((prev) => !prev)}
          >
            <span className="lab-switch__label">Explanations</span>
            <span className="lab-switch__track" aria-hidden="true">
              <span className="lab-switch__thumb" />
            </span>
          </button>
        </div>

        <div className="lab-telemetry">
          <div className="lab-metric">
            <span className="lab-metric__label">Water molecules</span>
            <strong className="lab-metric__value">{telemetry.waterCount}</strong>
            <span className="lab-metric__note">
              count is <strong>constant</strong> — water never disappears
            </span>
          </div>

          <div className="lab-metric lab-metric--right">
            <span className="lab-metric__label">Tails shielded from water</span>
            <strong className="lab-metric__value">{telemetry.shieldedPercent}%</strong>
            <span className="lab-metric__note">
              phospholipids: {telemetry.phospholipidCount} · bilayer:{" "}
              <strong className={`lab-status lab-status--${telemetry.status}`}>
                {STATUS_LABELS[telemetry.status]}
              </strong>
            </span>
          </div>
        </div>

        <div className="lab-start-row">
          <span className="lab-start-row__label">start</span>
          <div
            className="segmented"
            role="group"
            aria-label="Starting configuration"
            ref={presetPill.containerRef}
          >
            <span className="spring-pill" aria-hidden="true" ref={presetPill.pillRef} />
            <button
              ref={presetPill.registerItem(0)}
              type="button"
              aria-pressed={preset === "random"}
              onClick={() => handleReset("random")}
            >
              Random solution
            </button>
            <button
              ref={presetPill.registerItem(1)}
              type="button"
              aria-pressed={preset === "formed"}
              onClick={() => handleReset("formed")}
            >
              Formed bilayer
            </button>
          </div>
        </div>

        <div className="lab-stage" ref={stageRef}>
          <canvas
            ref={canvasRef}
            className="lab-canvas"
            aria-hidden="true"
            title="Tap or click anywhere to disrupt the bilayer"
            onPointerDown={handleCanvasPointerDown}
          />
          {telemetry.toastVisible && (
            <div className="lab-toast" role="status" aria-live="polite">
              Explosion: all molecules scattered, including water.
            </div>
          )}
          <p className="visually-hidden" aria-live="polite">
            Bilayer status: {STATUS_LABELS[telemetry.status]}. {telemetry.shieldedPercent} percent
            of hydrophobic tails shielded from water, with {telemetry.waterCount} water molecules
            and {telemetry.phospholipidCount} phospholipids.
          </p>
        </div>

        {reduceMotion && !running && (
          <p className="lab-motion-note muted small">
            Reduced motion is active, so the simulation starts paused. Use <strong>Play</strong>,{" "}
            <strong>Step</strong>, or <strong>Disrupt membrane</strong> to explore motion at your
            own pace.
          </p>
        )}

        {showExplanations && (
          <article className="lab-explain" aria-live="polite">
            <div className="lab-explain__head">
              <span className={`lab-explain__badge lab-explain__badge--${telemetry.status}`}>
                {explanation.badge}
              </span>
              <h2>{explanation.heading}</h2>
            </div>
            <p>{explanation.body}</p>
          </article>
        )}
      </section>

      <div className="lab-info-grid">
        <section className="panel" aria-labelledby="lab-key-heading">
          <p className="eyebrow">Visual key</p>
          <h2 id="lab-key-heading">Reading the simulation</h2>
          <ul className="lab-legend">
            <li>
              <span className="lab-swatch lab-swatch--head" aria-hidden="true" />
              <div>
                <strong>Hydrophilic phosphate head</strong>
                <span className="muted small">
                  Polar and water-attracted; orients outward toward water on both leaflets.
                </span>
              </div>
            </li>
            <li>
              <span className="lab-swatch lab-swatch--tails" aria-hidden="true" />
              <div>
                <strong>Hydrophobic fatty-acid tails</strong>
                <span className="muted small">
                  Non-polar hydrocarbon chains that avoid water and pack together inside the core.
                </span>
              </div>
            </li>
            <li>
              <span className="lab-swatch lab-swatch--water" aria-hidden="true" />
              <div>
                <strong>Water molecule (313 total)</strong>
                <span className="muted small">
                  Strictly conserved; thermal motion pushes water out of the non-polar core.
                </span>
              </div>
            </li>
            <li>
              <span className="lab-swatch lab-swatch--glow" aria-hidden="true" />
              <div>
                <strong>Warm hydrophobic shielding glow</strong>
                <span className="muted small">
                  Appears where tails shelter one another from water, merging into a continuous band
                  once the bilayer forms.
                </span>
              </div>
            </li>
          </ul>
          <p className="muted small">
            Schematic 2D cross-section: molecule counts (102 phospholipids, 313 water molecules) and
            interaction rates are tuned for clarity rather than real membrane scale.
          </p>
        </section>

        <section className="panel" aria-labelledby="lab-specimens-heading">
          <p className="eyebrow">Gallery &amp; references</p>
          <h2 id="lab-specimens-heading">See this membrane in 3D specimens</h2>
          <p className="muted small">
            Inspect the plasma membrane in context across eukaryotic and prokaryotic cells, then
            review the cited textbook sources behind the bilayer model.
          </p>
          <div className="lab-specimen-links">
            {membraneSpecimens.map((specimen) => (
              <button
                key={specimen.id}
                type="button"
                className="chip"
                onClick={() => navigateToStructure(specimen.id, "plasma-membrane")}
              >
                <span
                  className="specimen-dot"
                  style={{ "--dot-accent": specimen.accent } as CSSProperties}
                  aria-hidden="true"
                />
                <span>{specimen.name}</span>
              </button>
            ))}
          </div>
          <ul className="source-list">
            {ncbiSource && (
              <li>
                <a href={ncbiSource.url} target="_blank" rel="noreferrer noopener">
                  <span>{ncbiSource.title}</span>
                  <IconArrowUpRight />
                </a>
                <span className="muted small">
                  {ncbiSource.publisher} · {ncbiSource.edition} · lipid bilayer self-assembly
                </span>
              </li>
            )}
            {openStaxSource && (
              <li>
                <a href={openStaxSource.url} target="_blank" rel="noreferrer noopener">
                  <span>{openStaxSource.title}</span>
                  <IconArrowUpRight />
                </a>
                <span className="muted small">
                  {openStaxSource.publisher} · {openStaxSource.edition} · plasma membrane structure
                </span>
              </li>
            )}
          </ul>
        </section>
      </div>
    </>
  );
}
