import { Suspense, lazy, useRef, type KeyboardEvent } from "react";
import { IconBilayer, IconBolt } from "../components/Icons";
import { SimulatorLoadFallback, ViewerBoundary } from "../components/ViewerBoundary";
import { BilayerSimulator } from "../lab/BilayerSimulator";
import {
  effectiveReducedMotion,
  effectiveTheme,
  useSystemColorScheme,
  useSystemReducedMotion,
} from "../lib/media";
import { nextTabIndex } from "../lib/navigation";
import { useSlidingPill } from "../lib/use-sliding-pill";
import { useVanillaStore } from "../lib/use-vanilla-store";
import { appStore, type LabSimulationId } from "../state/app-store";

const ActionPotentialSimulator = lazy(() =>
  import("../lab/ActionPotentialSimulator").then((m) => ({
    default: m.ActionPotentialSimulator,
  })),
);

const LAB_TABS: Array<{ id: LabSimulationId; label: string }> = [
  { id: "bilayer", label: "Phospholipid bilayer" },
  { id: "action-potential", label: "Action potential" },
];

export function LabPage() {
  const activeTab = useVanillaStore(appStore, (state) => state.labSimulation);
  const reduceMotionSetting = useVanillaStore(appStore, (state) => state.settings.reduceMotion);
  const themeSetting = useVanillaStore(appStore, (state) => state.settings.theme);
  const systemReduced = useSystemReducedMotion();
  const systemScheme = useSystemColorScheme();
  const reduceMotion = effectiveReducedMotion(reduceMotionSetting, systemReduced);
  const resolvedTheme = effectiveTheme(themeSetting, systemScheme);
  const tabRefs = useRef<Array<HTMLButtonElement | null>>([]);
  const tabIndex = Math.max(
    0,
    LAB_TABS.findIndex((entry) => entry.id === activeTab),
  );
  const tabPill = useSlidingPill<HTMLButtonElement>(tabIndex, reduceMotion);

  function onTabKeyDown(event: KeyboardEvent<HTMLButtonElement>, index: number) {
    const next = nextTabIndex(event.key, index, LAB_TABS.length);
    if (next === null) return;
    event.preventDefault();
    const target = LAB_TABS[next];
    if (target) {
      appStore.getState().setLabSimulation(target.id);
      tabRefs.current[next]?.focus();
    }
  }

  return (
    <div className="page page--lab">
      <header className="page-header lab-header">
        <div className="lab-header__intro">
          <p className="eyebrow">
            {activeTab === "bilayer"
              ? "Interactive lab · membrane dynamics"
              : "Interactive lab · neural signaling"}
          </p>
          <div className="lab-header__title">
            <span className="lab-header__emblem" aria-hidden="true">
              {activeTab === "bilayer" ? <IconBilayer size={32} /> : <IconBolt size={24} />}
            </span>
            <h1>
              {activeTab === "bilayer"
                ? "Phospholipid bilayer: self-assembly simulator"
                : "Action potential: nerve impulse simulator"}
            </h1>
          </div>
          <p className="lede">
            {activeTab === "bilayer"
              ? "Phospholipids in water assemble themselves into a bilayer — disrupt it with a tap or click and watch it restore."
              : "Watch how voltage-gated Na⁺ and K⁺ channels trigger depolarization, repolarization, hyperpolarization, and saltatory conduction along a myelinated axon."}
          </p>
        </div>
        <div className="page-header__controls">
          <span className="badge badge--schematic">2D schematic simulation</span>
        </div>
      </header>

      <div className="tabs" role="tablist" aria-label="Lab simulations" ref={tabPill.containerRef}>
        <span className="spring-pill" aria-hidden="true" ref={tabPill.pillRef} />
        {LAB_TABS.map((entry, index) => {
          const registerPillItem = tabPill.registerItem(index);
          const selected = activeTab === entry.id;
          return (
            <button
              key={entry.id}
              ref={(element) => {
                tabRefs.current[index] = element;
                registerPillItem(element);
              }}
              type="button"
              role="tab"
              id={`lab-tab-${entry.id}`}
              aria-selected={selected}
              aria-controls={`lab-panel-${entry.id}`}
              tabIndex={selected ? 0 : -1}
              className={selected ? "tab tab--active" : "tab"}
              onClick={() => appStore.getState().setLabSimulation(entry.id)}
              onKeyDown={(event) => onTabKeyDown(event, index)}
            >
              {entry.label}
            </button>
          );
        })}
      </div>

      <div
        role="tabpanel"
        id={`lab-panel-${activeTab}`}
        aria-labelledby={`lab-tab-${activeTab}`}
        tabIndex={0}
        className="tab-panel"
      >
        {activeTab === "bilayer" ? (
          <ViewerBoundary
            fallback={
              <SimulatorLoadFallback
                title="Phospholipid bilayer simulator could not start"
                message="Reload the page, or inspect the plasma membrane structures in the Explore gallery."
              />
            }
          >
            <BilayerSimulator reduceMotion={reduceMotion} resolvedTheme={resolvedTheme} />
          </ViewerBoundary>
        ) : (
          <ViewerBoundary
            fallback={
              <SimulatorLoadFallback
                title="Action potential simulator could not start"
                message="Reload the page, or inspect the neuron structures in the Explore gallery."
              />
            }
          >
            <Suspense
              fallback={
                <div className="lab-card" role="status" aria-live="polite">
                  <p className="muted">Loading simulator…</p>
                </div>
              }
            >
              <ActionPotentialSimulator reduceMotion={reduceMotion} />
            </Suspense>
          </ViewerBoundary>
        )}
      </div>
    </div>
  );
}
