import {
  HEAD_RADIUS,
  SIM_HEIGHT,
  SIM_WIDTH,
  TAIL_LEN,
  WATER_RADIUS,
  type BilayerSimulation,
} from "./bilayer-engine";

export type SimulationTheme = "light" | "dark";

interface Palette {
  background: string;
  glowInner: string;
  glowMid: string;
  glowOuter: string;
  shockwave: string;
  waterHighlight: string;
  waterBody: string;
  waterStroke: string;
  tailStroke: string;
  headHighlight: string;
  headBody: string;
  headShadow: string;
  headStroke: string;
}

const PALETTES: Record<SimulationTheme, Palette> = {
  light: {
    background: "#fbfdff",
    glowInner: "rgba(246, 198, 78, 0.42)",
    glowMid: "rgba(244, 194, 78, 0.22)",
    glowOuter: "rgba(244, 194, 78, 0)",
    shockwave: "rgba(220, 74, 56, 0.52)",
    waterHighlight: "#d4edff",
    waterBody: "#70b9f4",
    waterStroke: "#3b82c4",
    tailStroke: "#6d6054",
    headHighlight: "#ff907d",
    headBody: "#e04132",
    headShadow: "#a12117",
    headStroke: "#741911",
  },
  dark: {
    background: "#101319",
    glowInner: "rgba(255, 202, 78, 0.34)",
    glowMid: "rgba(255, 192, 64, 0.16)",
    glowOuter: "rgba(255, 192, 64, 0)",
    shockwave: "rgba(255, 118, 99, 0.56)",
    waterHighlight: "#bce3ff",
    waterBody: "#4ea3ea",
    waterStroke: "#8ccfff",
    tailStroke: "#c7b8a5",
    headHighlight: "#ff9a87",
    headBody: "#e84938",
    headShadow: "#a22218",
    headStroke: "#4d100b",
  },
};

interface SpriteSet {
  glow: HTMLCanvasElement;
  glowHalf: number;
  water: HTMLCanvasElement;
  waterHalf: number;
  head: HTMLCanvasElement;
  headHalf: number;
}

const spriteCache = new Map<SimulationTheme, SpriteSet>();

function createSpriteCanvas(size: number): HTMLCanvasElement | null {
  if (typeof document === "undefined") return null;
  const canvas = document.createElement("canvas");
  canvas.width = size;
  canvas.height = size;
  return canvas;
}

function buildSprites(theme: SimulationTheme): SpriteSet | null {
  const cached = spriteCache.get(theme);
  if (cached) return cached;

  const palette = PALETTES[theme];
  const scale = 2;

  // 1. Warm hydrophobic core glow halo sprite
  const glowRadius = 32;
  const glowHalf = glowRadius;
  const glowCanvas = createSpriteCanvas(glowRadius * 2 * scale);
  if (!glowCanvas) return null;
  const gCtx = glowCanvas.getContext("2d");
  if (!gCtx) return null;
  gCtx.scale(scale, scale);
  const glowGrad = gCtx.createRadialGradient(glowHalf, glowHalf, 2, glowHalf, glowHalf, glowRadius);
  glowGrad.addColorStop(0, palette.glowInner);
  glowGrad.addColorStop(0.55, palette.glowMid);
  glowGrad.addColorStop(1, palette.glowOuter);
  gCtx.fillStyle = glowGrad;
  gCtx.beginPath();
  gCtx.arc(glowHalf, glowHalf, glowRadius, 0, Math.PI * 2);
  gCtx.fill();

  // 2. Water molecule droplet sprite
  const waterHalf = Math.ceil(WATER_RADIUS + 2);
  const waterCanvas = createSpriteCanvas(waterHalf * 2 * scale);
  if (!waterCanvas) return null;
  const wCtx = waterCanvas.getContext("2d");
  if (!wCtx) return null;
  wCtx.scale(scale, scale);
  const waterGrad = wCtx.createRadialGradient(
    waterHalf - 1.1,
    waterHalf - 1.1,
    0.5,
    waterHalf,
    waterHalf,
    WATER_RADIUS,
  );
  waterGrad.addColorStop(0, palette.waterHighlight);
  waterGrad.addColorStop(0.55, palette.waterBody);
  waterGrad.addColorStop(1, palette.waterBody);
  wCtx.fillStyle = waterGrad;
  wCtx.beginPath();
  wCtx.arc(waterHalf, waterHalf, WATER_RADIUS, 0, Math.PI * 2);
  wCtx.fill();
  wCtx.lineWidth = 1.0;
  wCtx.strokeStyle = palette.waterStroke;
  wCtx.stroke();

  // 3. Coral-red phospholipid hydrophilic head sprite
  const headHalf = Math.ceil(HEAD_RADIUS + 2);
  const headCanvas = createSpriteCanvas(headHalf * 2 * scale);
  if (!headCanvas) return null;
  const hCtx = headCanvas.getContext("2d");
  if (!hCtx) return null;
  hCtx.scale(scale, scale);
  const headGrad = hCtx.createRadialGradient(
    headHalf - 1.8,
    headHalf - 1.8,
    0.8,
    headHalf,
    headHalf,
    HEAD_RADIUS,
  );
  headGrad.addColorStop(0, palette.headHighlight);
  headGrad.addColorStop(0.52, palette.headBody);
  headGrad.addColorStop(1, palette.headShadow);
  hCtx.fillStyle = headGrad;
  hCtx.beginPath();
  hCtx.arc(headHalf, headHalf, HEAD_RADIUS, 0, Math.PI * 2);
  hCtx.fill();
  hCtx.lineWidth = 1.15;
  hCtx.strokeStyle = palette.headStroke;
  hCtx.stroke();

  const set: SpriteSet = {
    glow: glowCanvas,
    glowHalf,
    water: waterCanvas,
    waterHalf,
    head: headCanvas,
    headHalf,
  };
  spriteCache.set(theme, set);
  return set;
}

export function renderBilayerFrame(
  ctx: CanvasRenderingContext2D,
  sim: BilayerSimulation,
  cssWidth: number,
  cssHeight: number,
  theme: SimulationTheme,
): void {
  const palette = PALETTES[theme];
  const sprites = buildSprites(theme);
  const scaleX = cssWidth / SIM_WIDTH;
  const scaleY = cssHeight / SIM_HEIGHT;

  ctx.save();
  ctx.scale(scaleX, scaleY);

  // 1. Clean aqueous chamber backdrop.
  ctx.fillStyle = palette.background;
  ctx.fillRect(0, 0, SIM_WIDTH, SIM_HEIGHT);

  // 2. Warm golden hydrophobic glow behind shielded tails.
  for (let i = 0; i < sim.phospholipids.length; i += 1) {
    const lipid = sim.phospholipids[i]!;
    if (lipid.shielded <= 0.1) continue;
    const alpha = Math.min(1, (lipid.shielded - 0.08) / 0.85);
    const gx = lipid.x + Math.cos(lipid.angle) * (TAIL_LEN * 0.62);
    const gy = lipid.y + Math.sin(lipid.angle) * (TAIL_LEN * 0.62);

    ctx.globalAlpha = alpha;
    if (sprites) {
      ctx.drawImage(
        sprites.glow,
        gx - sprites.glowHalf,
        gy - sprites.glowHalf,
        sprites.glowHalf * 2,
        sprites.glowHalf * 2,
      );
    } else {
      ctx.fillStyle = palette.glowMid;
      ctx.beginPath();
      ctx.arc(gx, gy, 24, 0, Math.PI * 2);
      ctx.fill();
    }
  }
  ctx.globalAlpha = 1;

  // 3. Expanding explosion shockwave ring right after disruption.
  if (sim.lastBlast && sim.lastBlast.age < 0.65) {
    const progress = sim.lastBlast.age / 0.65;
    const radius = 16 + progress * 210;
    ctx.save();
    ctx.globalAlpha = Math.max(0, 1 - progress);
    ctx.strokeStyle = palette.shockwave;
    ctx.lineWidth = 3 * (1 - progress) + 1;
    ctx.beginPath();
    ctx.arc(sim.lastBlast.x, sim.lastBlast.y, radius, 0, Math.PI * 2);
    ctx.stroke();
    ctx.restore();
  }

  // 4. Water molecules (all 313 strictly conserved).
  if (sprites) {
    const wh = sprites.waterHalf;
    const ws = wh * 2;
    for (let i = 0; i < sim.waters.length; i += 1) {
      const w = sim.waters[i]!;
      ctx.drawImage(sprites.water, w.x - wh, w.y - wh, ws, ws);
    }
  } else {
    ctx.fillStyle = palette.waterBody;
    ctx.strokeStyle = palette.waterStroke;
    ctx.lineWidth = 1;
    for (let i = 0; i < sim.waters.length; i += 1) {
      const w = sim.waters[i]!;
      ctx.beginPath();
      ctx.arc(w.x, w.y, WATER_RADIUS, 0, Math.PI * 2);
      ctx.fill();
      ctx.stroke();
    }
  }

  // 5. Phospholipid paired hydrophobic fatty-acid tails.
  ctx.strokeStyle = palette.tailStroke;
  ctx.lineWidth = 1.85;
  ctx.lineCap = "round";
  ctx.lineJoin = "round";
  ctx.beginPath();
  for (let i = 0; i < sim.phospholipids.length; i += 1) {
    const lipid = sim.phospholipids[i]!;
    const cos = Math.cos(lipid.angle);
    const sin = Math.sin(lipid.angle);
    // Perpendicular unit vector.
    const px = -sin;
    const py = cos;

    // Straight saturated tail chain.
    const sStartX = lipid.x + cos * (HEAD_RADIUS * 0.55) + px * 2.2;
    const sStartY = lipid.y + sin * (HEAD_RADIUS * 0.55) + py * 2.2;
    const sEndX = lipid.x + cos * TAIL_LEN + px * 2.5;
    const sEndY = lipid.y + sin * TAIL_LEN + py * 2.5;
    ctx.moveTo(sStartX, sStartY);
    ctx.lineTo(sEndX, sEndY);

    // Subtle kinked unsaturated tail chain.
    const kStartX = lipid.x + cos * (HEAD_RADIUS * 0.55) - px * 2.2;
    const kStartY = lipid.y + sin * (HEAD_RADIUS * 0.55) - py * 2.2;
    const kMidX = lipid.x + cos * (TAIL_LEN * 0.52) - px * (2.3 + lipid.kinkSign * 1.1);
    const kMidY = lipid.y + sin * (TAIL_LEN * 0.52) - py * (2.3 + lipid.kinkSign * 1.1);
    const kEndX = lipid.x + cos * (TAIL_LEN - 1.2) - px * (2.6 + lipid.kinkSign * 1.6);
    const kEndY = lipid.y + sin * (TAIL_LEN - 1.2) - py * (2.6 + lipid.kinkSign * 1.6);
    ctx.moveTo(kStartX, kStartY);
    ctx.lineTo(kMidX, kMidY);
    ctx.lineTo(kEndX, kEndY);
  }
  ctx.stroke();

  // 6. Coral-red hydrophilic heads layered over tail attachment points.
  if (sprites) {
    const hh = sprites.headHalf;
    const hs = hh * 2;
    for (let i = 0; i < sim.phospholipids.length; i += 1) {
      const lipid = sim.phospholipids[i]!;
      ctx.drawImage(sprites.head, lipid.x - hh, lipid.y - hh, hs, hs);
    }
  } else {
    ctx.fillStyle = palette.headBody;
    ctx.strokeStyle = palette.headStroke;
    ctx.lineWidth = 1.1;
    for (let i = 0; i < sim.phospholipids.length; i += 1) {
      const lipid = sim.phospholipids[i]!;
      ctx.beginPath();
      ctx.arc(lipid.x, lipid.y, HEAD_RADIUS, 0, Math.PI * 2);
      ctx.fill();
      ctx.stroke();
    }
  }

  ctx.restore();
}
